algorithms.pseudocode:
function MOORE_CHECK(G):
    assert DIAMETER_AT_MOST_2(G)
    n <- number of vertices of G
    D <- max over v of deg(v)
    return (n <= D*D + 1, n, D*D + 1)

function DIAMETER_AT_MOST_2(G):
    for each unordered pair {a,b} of distinct vertices:
        if a not adjacent b and N(a) cap N(b) is empty:
            return False
    return True

function CHERRY_CHECK(G):
    assert C4_FREE(G)
    n <- number of vertices of G
    lhs <- sum over v of C(deg(v), 2)
    rhs <- C(n, 2)
    return (lhs <= rhs, lhs, rhs)

function C4_FREE(G):
    for each unordered pair {a,b} of distinct vertices:
        if |N(a) cap N(b)| >= 2: return False
    return True
